import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.Dkh1x705.js";var i=JSON.parse(`{"title":"Версии","description":"","frontmatter":{},"headers":[],"relativePath":"versions.md","filePath":"versions.md","lastUpdated":0}`),a={name:`versions.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="версии" tabindex="-1">Версии <a class="header-anchor" href="#версии" aria-label="Permalink to “Версии”">​</a></h1><p>Текущая версия расширения — <strong>3.0.0</strong>. Обновления приходят автоматически из магазина браузера; проверить установленную версию можно в попапе настроек — внизу показан номер со ссылкой на эту страницу.</p><h2 id="как-обновляется-расширение" tabindex="-1">Как обновляется расширение <a class="header-anchor" href="#как-обновляется-расширение" aria-label="Permalink to “Как обновляется расширение”">​</a></h2><ul><li><strong>Chrome и Яндекс.Браузер</strong> — через Chrome Web Store, обновление ставится фоново; чтобы применить сразу, нажмите «Обновить» на странице расширений.</li><li><strong>Firefox</strong> — через addons.mozilla.org, обновление проверяется браузером.</li><li><strong>Ручная установка</strong> — архивы и исходники лежат в <a href="https://github.com/vibecodinguser/yamapper/releases" target="_blank" rel="noreferrer">релизах на GitHub</a>.</li></ul><p>После обновления расширения обновите вкладку карты: старые content scripts остаются в уже открытой странице и работают по-старому.</p><h2 id="v3-0-0" tabindex="-1">3.0.0 <a class="header-anchor" href="#v3-0-0" aria-label="Permalink to “3.0.0”">​</a></h2><p>Крупное обновление интерфейса и разрешений.</p><ul><li><strong>Попап настроек в шапке редактора</strong> вместо боковой панели: кнопка-шестерёнка среди нативных кнопок, внутри три вкладки — «Редактор», «Модерация», «Стиль».</li><li><strong>Необязательные разрешения Яндекса.</strong> Пока «Заметки» и «НСПД» выключены, расширение не обращается к Яндексу и не открывает окно входа. Доступ запрашивается по кнопке, а не при установке.</li><li><strong>Следование теме и языку редактора.</strong> Ручные переключатели темы и языка убраны: расширение всегда оформлено и переведено так же, как редактор.</li><li><strong>Разрез растительности и водоёмов</strong> — новая кнопка в нативном тулбаре.</li><li><strong>Заметки</strong>: группы, фильтры по виду/группе/видимости, сортировка, отметка нескольких заметок, оформление (цвет, прозрачность, заливка, узор, подпись), подтверждение удаления как в нативном редакторе.</li><li><strong>Внешние геосервисы</strong>: порядок пунктов меняется перетаскиванием и запоминается; в раздельном виде контролы Nakarte скрыты.</li><li><strong>НСПД</strong>: кнопка «Разрешить доступ» прямо в строке настройки.</li><li><strong>Наблюдение за объектами</strong>: нативная иконка обновления, пауза при ограничении частоты запросов.</li><li><strong>Автообновление после загрузки</strong> — переключатель, который перезагружает карту, когда данные записаны.</li></ul><h2 id="v2-4" tabindex="-1">2.4.x <a class="header-anchor" href="#v2-4" aria-label="Permalink to “2.4.x”">​</a></h2><ul><li>Кнопка «Загрузка из НСПД» включена по умолчанию.</li><li>Снятие объекта с наблюдения из меню «Ещё», пауза опроса после ответа 429.</li><li>Счётчик вершин выключен, пока его не включат в настройках.</li><li>Инструмент разреза: нативные маркеры точек разреза, общий инструмент для растительности и водоёмов.</li></ul><h2 id="v2-3" tabindex="-1">2.3.x <a class="header-anchor" href="#v2-3" aria-label="Permalink to “2.3.x”">​</a></h2><ul><li>Настройки сгруппированы в раскрывающиеся секции; ссылка «Предложить функцию» вместо старой формы обратной связи.</li><li>Заметки: редизайн карточки, строка инструментов списка, бейдж количества в группе, адаптивная карточка на всю ширину, подтверждение удаления.</li><li>Наблюдение за объектами: лента в формате нативной «Мои правки», иконки категорий, вкладка «Мои объекты».</li></ul><h2 id="v1-4" tabindex="-1">1.4.x <a class="header-anchor" href="#v1-4" aria-label="Permalink to “1.4.x”">​</a></h2><ul><li>Фильтр истории правок: выпадающий фильтр по действию, переработанная подгрузка истории по периодам.</li><li>Синхронизация дат в календаре загрузки и в блокноте.</li><li>Стили интерфейса синхронизированы со шрифтами Народной карты.</li><li>Раздельный вид: сохранение параметров и слоёв Nakarte, устранение рассинхронизации центра и зума.</li><li>Добавлен геосервис ЭтоМесто.</li></ul><h2 id="v1-3" tabindex="-1">1.3.x <a class="header-anchor" href="#v1-3" aria-label="Permalink to “1.3.x”">​</a></h2><ul><li>Синхронизация дат между пикером и блокнотом.</li><li>Отмена выбора точки в блокноте.</li><li>Счётчик вершин для линейных объектов.</li><li>Кнопка фильтра правок выключена по умолчанию.</li></ul><h2 id="v1-2" tabindex="-1">1.2.x и раньше <a class="header-anchor" href="#v1-2" aria-label="Permalink to “1.2.x и раньше”">​</a></h2><ul><li>Следование теме редактора для элементов управления.</li><li>Стабильный id расширения в Chrome.</li><li>Загрузка точек и первые версии конвертеров.</li></ul><h2 id="формат-версии" tabindex="-1">Формат версий <a class="header-anchor" href="#формат-версии" aria-label="Permalink to “Формат версий”">​</a></h2><p>Номер версии — <code>MAJOR.MINOR.PATCH</code>:</p><ul><li><strong>MAJOR</strong> — заметные изменения интерфейса или поведения, которые требуют привыкания (например, переезд настроек из боковой панели в попап).</li><li><strong>MINOR</strong> — новые функции, обратно совместимые.</li><li><strong>PATCH</strong> — исправления без новых функций.</li></ul><p>Полная история коммитов — в <a href="https://github.com/vibecodinguser/yamapper/commits/master" target="_blank" rel="noreferrer">репозитории</a>.</p>`,22)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};